<?php
namespace App\Http\Controllers\Sales;use App\Http\Controllers\Controller;use App\Models\{CorporateAccount,CorporateInvoice,LocalPurchaseOrder,TravelAgent};use App\Services\Sales\CorporateSalesService;use Illuminate\Http\Request;
class CorporateInvoiceController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('sales.invoices',['invoices'=>CorporateInvoice::where('property_id',$p)->with('company','agent','lpo','items','payments')->latest()->paginate(40),'companies'=>CorporateAccount::where('property_id',$p)->where('status','active')->get(),'agents'=>TravelAgent::where('property_id',$p)->where('status','active')->get(),'lpos'=>LocalPurchaseOrder::where('property_id',$p)->where('status','open')->with('company')->get()]);}public function store(Request $r,CorporateSalesService $svc){$d=$r->validate(['corporate_account_id'=>'nullable|exists:corporate_accounts,id','travel_agent_id'=>'nullable|exists:travel_agents,id','local_purchase_order_id'=>'nullable|exists:local_purchase_orders,id','invoice_date'=>'nullable|date','due_date'=>'nullable|date','notes'=>'nullable|string','item_description'=>'required|array|min:1','item_description.*'=>'required|string','quantity'=>'required|array','quantity.*'=>'required|numeric|min:0.001','unit_price'=>'required|array','unit_price.*'=>'required|numeric|min:0','tax_amount'=>'nullable|array','tax_amount.*'=>'nullable|numeric|min:0']);if(empty($d['corporate_account_id'])&&empty($d['travel_agent_id']))return back()->withErrors(['corporate_account_id'=>'Select a corporate account or travel agent.'])->withInput();$items=[];foreach($d['item_description'] as $i=>$desc)$items[]=['description'=>$desc,'quantity'=>(float)$d['quantity'][$i],'unit_price'=>(float)$d['unit_price'][$i],'tax_amount'=>(float)($d['tax_amount'][$i]??0)];try{$inv=$svc->createInvoice(['property_id'=>auth()->user()->property_id,'corporate_account_id'=>$d['corporate_account_id']??null,'travel_agent_id'=>$d['travel_agent_id']??null,'local_purchase_order_id'=>$d['local_purchase_order_id']??null,'invoice_date'=>$d['invoice_date']??today(),'due_date'=>$d['due_date']??null,'notes'=>$d['notes']??null],$items,auth()->id());return back()->with('success','Invoice '.$inv->invoice_no.' created and posted to Accounts Receivable.');}catch(\Throwable $e){return back()->withErrors(['invoice'=>$e->getMessage()])->withInput();}}public function pay(Request $r,CorporateInvoice $invoice,CorporateSalesService $svc){abort_unless($invoice->property_id===auth()->user()->property_id,403);$d=$r->validate(['amount'=>'required|numeric|min:0.01','method'=>'required|in:cash,bank_transfer,mtn_momo,airtel_money,card_pos,cheque','reference'=>'nullable|max:100','payment_date'=>'nullable|date']);try{$svc->pay($invoice,$d,auth()->id());return back()->with('success','Corporate payment received.');}catch(\Throwable $e){return back()->withErrors(['payment'=>$e->getMessage()]);}}}
